    public static bool IsKind(string kind)
    {
        for (var i = 0; i < Kinds.Length; i++)
            if (Kinds[i] == kind) return true;
        return false;
    }

    public static string[] SectionNames(string kind)
    {
        if (!Sections.TryGetValue(kind ?? "", out var bySection)) return Array.Empty<string>();
        var names = new List<string>(bySection.Count);
        foreach (var kv in bySection) names.Add(kv.Key);
        return names.ToArray();
    }

    public static bool TryGetSection(string kind, string section, out string[] props)
    {
        props = null;
        return Sections.TryGetValue(kind ?? "", out var bySection) &&
               bySection.TryGetValue(section ?? "", out props);
    }
